@app.post("/repos/sync")
def sync_repositories(current_user: User = Depends(get_current_user)):
    db = SessionLocal()
    platform = current_user.platform_tokens
    
    services = {
        "github": GitHubService(),
        "gitlab": GitLabService(),
        "gitea": GiteaService()
    }
    
    for plat, token in platform.items():
        if plat in services:
            repos = services[plat].list_repos(token)
            for repo_data in repos:
                db_repo = Repository(
                    platform=plat,
                    repo_id=str(repo_data["id"]),
                    full_name=repo_data["full_name"],
                    owner=repo_data["owner"]["login"],
                    private=repo_data.get("private", False),
                    metadata=repo_data
                )
                db.merge(db_repo)
    db.commit()
    db.close()
    return {"status": "success", "message": "Repositories synced"}

@app.get("/repos", response_model=List[Dict])
def list_repositories(current_user: User = Depends(get_current_user)):
    db = SessionLocal()
    repos = db.query(Repository).all()
    db.close()
    return [repo.metadata for repo in repos]

